sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float sliceCount;
uniform float maxShift;
uniform float density;
uniform float rate;
uniform float chromatic;
uniform float seed;
uniform float vertical;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float t = floor(time * rate);
    float axisPos = vertical > 0.5 ? coord.x : coord.y;
    float len = vertical > 0.5 ? size.x : size.y;
    float row = floor(axisPos / len * floor(sliceCount + 0.5));
    float rnd = hash21(float2(row + seed, t));
    float on = step(1.0 - density, hash21(float2(row * 1.7 + seed, t + 3.0)));
    float sh = (rnd - 0.5) * 2.0 * maxShift * on;
    float2 dir = vertical > 0.5 ? float2(0.0, 1.0) : float2(1.0, 0.0);
    float4 cr = tex(coord + dir * (sh + chromatic * on));
    float4 cg = tex(coord + dir * sh);
    float4 cb = tex(coord + dir * (sh - chromatic * on));
    return fin(c, float4(cr.r, cg.g, cb.b, cg.a), opacity);
}
